from itertools import combinations

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i, j in combinations(range(n), 2):
        if j > i:
            dc = j - i
            dr = perm[j] - perm[i]
            v = (dr, dc)
            if v in vectors:
                return False
            vectors.add(v)
    return True

# Try backtracking search with constraints
def solve_costas(n, fixed={}):
    perm = [None] * n
    for col, row in fixed.items():
        perm[col] = row

    used_rows = set(v for v in perm if v is not None)

    def get_vectors(perm, col):
        """Get all displacement vectors involving column col"""
        vecs = []
        for c in range(col):
            if perm[c] is not None:
                dc = col - c
                dr = perm[col] - perm[c]
                vecs.append((dr, dc))
        return vecs

    def backtrack(col, used_rows, vectors):
        if col == n:
            return perm[:]

        # Skip fixed columns
        if perm[col] is not None:
            # Check if this fixed value is consistent
            new_vecs = get_vectors(perm, col)
            for v in new_vecs:
                if v in vectors:
                    return None
            new_vectors = vectors | set(new_vecs)
            result = backtrack(col + 1, used_rows, new_vectors)
            return result

        for row in range(n):
            if row in used_rows:
                continue
            perm[col] = row
            new_vecs = get_vectors(perm, col)
            conflict = False
            for v in new_vecs:
                if v in vectors:
                    conflict = True
                    break
            if not conflict:
                new_vectors = vectors | set(new_vecs)
                used_rows.add(row)
                result = backtrack(col + 1, used_rows, new_vectors)
                if result is not None:
                    return result
                used_rows.remove(row)
            perm[col] = None

        return None

    return backtrack(0, used_rows, set())

